      {/* Host Experience & Unique Selling Points */}
      <div className="flex flex-col gap-6">
        {/* Host card */}
        <div className="flex flex-row items-start gap-4">
          <Avatar src={user?.image} userName={user?.firstname} />
          <div className="flex flex-col gap-0.5">
            <div className="font-semibold text-neutral-800 text-[15px]">Hôte : {user?.firstname}</div>
            <div className="text-sm text-neutral-500 font-light">
              6 mois d&apos;expérience en tant qu&apos;hôte sur Alasbnb
            </div>
          </div>
        </div>

        {/* Dynamic highlights */}
        {avgRating >= 4.5 && (
          <div className="flex flex-row items-start gap-4">
            <FiAward size={28} className="text-neutral-700 mt-1" />
            <div className="flex flex-col gap-0.5">
              <div className="font-semibold text-neutral-800 text-[15px]">Très bien noté par les voyageurs</div>
              <div className="text-sm text-neutral-500 font-light">
                100 % des voyageurs ont attribué 5 étoiles à ce logement.
              </div>
            </div>
          </div>
        )}

        {amenities.includes("Piscine") && (
          <div className="flex flex-row items-start gap-4">
            <TbPool size={28} className="text-neutral-700 mt-1" />
            <div className="flex flex-col gap-0.5">
              <div className="font-semibold text-neutral-800 text-[15px]">Offrez-vous un plongeon</div>
              <div className="text-sm text-neutral-500 font-light">
                C&apos;est l&apos;un des rares logements de la région disposant d&apos;une piscine.
              </div>
            </div>
          </div>
        )}

        <div className="flex flex-row items-start gap-4">
          <FiKey size={28} className="text-neutral-700 mt-1" />
          <div className="flex flex-col gap-0.5">
            <div className="font-semibold text-neutral-800 text-[15px]">Procédure d&apos;arrivée exceptionnelle</div>
            <div className="text-sm text-neutral-500 font-light">
              Les voyageurs récents ont attribué 5 étoiles à la procédure d&apos;arrivée.
            </div>
          </div>
        </div>
      </div>
      <hr />

      {/* Auto-translation banner */}
      <div className="bg-neutral-50 border border-neutral-100 rounded-2xl p-4 flex flex-col gap-1">
        <div className="text-xs text-neutral-500 font-light leading-relaxed">
          Certaines informations ont été traduites automatiquement. <span className="underline font-semibold cursor-pointer text-neutral-800">Afficher le texte d&apos;origine</span>
        </div>
      </div>
      <hr />

      {/* Description */}
      <div className="flex flex-col gap-2">
        <p className="text-[15px] leading-relaxed text-neutral-600 font-light whitespace-pre-line">
          {description}
        </p>
      </div>
      <hr />

      {/* Sleep Component */}
      <Sleep bedrooms={bedrooms} />
      <hr />

      {/* Offers Component */}
      <Offers amenities={amenities} />
      <hr />

      {/* Map location */}
      <div className="flex flex-col gap-1">
        <p className="text-xl font-semibold text-neutral-800">Où se situe le logement</p>
        <p className="text-sm font-light text-neutral-500">
          {location?.city ? `${location.city}, ` : ""}{location?.country || locationValue}
        </p>
      </div>
      <Map center={coordinates} />
    </div>
  );
}

export default ListingInfo;

"use client";

import { safeListing } from "@/types";
import { GoogleMap, MarkerF, useJsApiLoader } from "@react-google-maps/api";
import { useMemo } from "react";
import { useRouter } from "next/navigation";

type Props = {
  listings: safeListing[];
  className?: string;
};

const MAP_STYLES: google.maps.MapTypeStyle[] = [
  { elementType: "geometry", stylers: [{ color: "#f5f5f5" }] },
  { elementType: "labels.icon", stylers: [{ visibility: "off" }] },
  { elementType: "labels.text.fill", stylers: [{ color: "#616161" }] },
  { elementType: "labels.text.stroke", stylers: [{ color: "#f5f5f5" }] },
  { featureType: "poi", elementType: "geometry", stylers: [{ color: "#eeeeee" }] },
  { featureType: "poi.park", elementType: "geometry", stylers: [{ color: "#e5e5e5" }] },
  { featureType: "road", elementType: "geometry", stylers: [{ color: "#ffffff" }] },
  { featureType: "road.highway", elementType: "geometry", stylers: [{ color: "#dadada" }] },
  { featureType: "transit.line", elementType: "geometry", stylers: [{ color: "#e5e5e5" }] },
  { featureType: "water", elementType: "geometry", stylers: [{ color: "#c9c9c9" }] },
];

function createPriceMarkerSvg(price: number) {
  const label = `€${price}`;
  const width = Math.max(44, 16 + label.length * 8);
  const height = 32;
  const radius = 16;
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
      <rect x="1" y="1" width="${width - 2}" height="${height - 2}" rx="${radius}" ry="${radius}" fill="#ffffff" stroke="#111827" stroke-width="1" />
      <text x="${width / 2}" y="${height / 2 + 5}" font-family="Arial, sans-serif" font-size="13" fill="#111827" text-anchor="middle" font-weight="600">${label}</text>
    </svg>
  `;

  return {
    url: `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`,
    size: { width, height },
  };
}

export default function MapListings({ listings, className }: Props) {
  const router = useRouter();
  const { isLoaded, loadError } = useJsApiLoader({
    googleMapsApiKey: process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY!,
    id: "search-map-script",
  });

  const markers = useMemo(() => {
    return listings
      .filter((listing) => listing.location?.lat && listing.location?.lng)
      .map((listing) => ({
        id: listing.id,
        price: listing.pricePerNight,
        position: {
          lat: listing.location.lat,
          lng: listing.location.lng,
        },
      }));
  }, [listings]);

  const center = useMemo(() => {
    if (markers.length === 0) {
      return { lat: 20, lng: 0 };
    }

    const avgLat = markers.reduce((sum, marker) => sum + marker.position.lat, 0) / markers.length;
    const avgLng = markers.reduce((sum, marker) => sum + marker.position.lng, 0) / markers.length;
    return { lat: avgLat, lng: avgLng };
  }, [markers]);

  if (loadError) {
    return (
      <div className={className || "h-[70vh] rounded-2xl bg-neutral-100 flex items-center justify-center text-sm text-neutral-400"}>
        Erreur de chargement de la carte
      </div>
    );
  }

  if (!isLoaded) {
    return <div className={className || "h-[70vh] rounded-2xl bg-neutral-200 animate-pulse"} />;
  }

  return (
    <GoogleMap
      mapContainerClassName={className || "h-[70vh] rounded-2xl w-full border border-neutral-100 shadow-sm"}
      center={center}
      zoom={markers.length > 0 ? 12 : 2}
      options={{
        styles: MAP_STYLES,
        zoomControl: true,
        mapTypeControl: false,
        streetViewControl: false,
        fullscreenControl: false,
        clickableIcons: false,
        scrollwheel: false,
      }}
    >
      {markers.map((marker) => {
        const icon = createPriceMarkerSvg(marker.price);
        return (
          <MarkerF
            key={marker.id}
            position={marker.position}
            onClick={() => router.push(`/listings/${marker.id}`)}
            icon={{
              url: icon.url,
              scaledSize: new window.google.maps.Size(icon.size.width, icon.size.height),
              anchor: new window.google.maps.Point(icon.size.width / 2, icon.size.height / 2),
            }}
          />
        );
      })}
    </GoogleMap>
  );
}

