                  >
                    <source src="https://a0.muscache.com/videos/search-bar-icons/webm/balloon-twirl.webm" type="video/webm" />
                    <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/balloon-twirl.mov" type="video/mp4" />
                  </video>
                  <span className="tracking-wide">{t.experiences}</span>
                </div>

              </div>

              {/* Compact Search Bar (Visible only when scrolled) */}
              <div className={`flex w-auto justify-center transition-all duration-300 ${isScrolled ? "opacity-100 scale-100 translate-y-0 visible relative pointer-events-auto" : "opacity-0 scale-95 translate-y-4 invisible absolute pointer-events-none"}`}>
                 <div
                   onClick={searchModal.onOpen}
                   className="border-[1px] w-full py-1 pl-2 pr-1 rounded-full shadow-md hover:shadow-lg transition cursor-pointer flex flex-row items-center justify-between text-[15px] font-medium text-gray-800 bg-white"
                 >
                   <div className="flex flex-row items-center gap-2 px-3 hover:bg-neutral-100 rounded-full transition py-2">
                     <video
                       autoPlay
                       muted
                       playsInline
                       className="w-5 h-5 object-cover bg-transparent outline-none drop-shadow-sm"
                     >
                       <source src="https://a0.muscache.com/videos/search-bar-icons/webm/house-selected.webm#t=0.001" type="video/webm" />
                       <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/house-selected.mov#t=0.001" type="video/mp4" />
                     </video>
                     <span className="font-semibold">{t.anywhere || "N'importe où"}</span>
                   </div>
                   <div className="px-4 border-l-[1px] border-r-[1px] border-gray-200 flex-1 text-center py-2 hover:bg-neutral-100 rounded-full transition font-semibold">
                     Dates flexibles
                   </div>
                   <div className="flex flex-row items-center gap-3 pl-4 pr-1 py-1 hover:bg-neutral-100 rounded-full transition">
                     <span className="text-gray-500">{t.addguests || "Ajouter des voyageurs"}</span>
                     <div className="p-2 bg-rose-500 rounded-full text-white inline-flex items-center justify-center">
                       <BiSearch size={16} className="font-bold" />
