import prisma from "@/lib/prismadb";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";
import { getServerSession } from "next-auth/next";
import { cache } from "react";

export async function getSession() {
  return await getServerSession(authOptions);
}

const getCurrentUser = cache(async () => {
  try {
    const session = await getSession();

    if (!session?.user?.email) {
      return null;
    }

    const currentUser = await prisma.user.findUnique({
      where: {
        email: session.user.email as string,
      },
    });

    if (!currentUser) {
      return null;
    }
    return {
      ...currentUser,
      createdAt: currentUser.createdAt.toISOString(),
      updatedAt: currentUser.updatedAt.toISOString(),
      emailVerified: currentUser.emailVerified?.toISOString() || null,
      deletedAt: currentUser.deletedAt?.toISOString() || null,
    };
  } catch (error: any) {
    console.log(
      " ~ file: getCurrentUser.ts:13 ~ getCurrentUser ~ error:",
      error
    );
    return null;
  }
});

export default getCurrentUser;

import prisma from "@/lib/prismadb";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";
import { getServerSession } from "next-auth/next";
import { cache } from "react";

export async function getSession() {
  return await getServerSession(authOptions);
}

const getCurrentUser = cache(async () => {
  try {
    const session = await getSession();

    if (!session?.user?.email) {
      return null;
    }

    const currentUser = await prisma.user.findUnique({
      where: {
        email: session.user.email as string,
      },
    });

    if (!currentUser) {
      const displayName = session.user.name || "User";
      const [firstname, ...rest] = displayName.split(" ");
      const lastname = rest.join(" ");

      const createdUser = await prisma.user.create({
        data: {
          email: session.user.email as string,
          firstname: firstname || "User",
          lastname: lastname || "",
          image: session.user.image || null,
          savedListingIds: [],
          savedExperienceIds: [],
        },
      });

      return {
        ...createdUser,
        createdAt: createdUser.createdAt.toISOString(),
        updatedAt: createdUser.updatedAt.toISOString(),
        emailVerified: createdUser.emailVerified?.toISOString() || null,
        deletedAt: createdUser.deletedAt?.toISOString() || null,
      };
    }

    return {
      ...currentUser,
      createdAt: currentUser.createdAt.toISOString(),
      updatedAt: currentUser.updatedAt.toISOString(),
      emailVerified: currentUser.emailVerified?.toISOString() || null,
      deletedAt: currentUser.deletedAt?.toISOString() || null,
    };
  } catch (error: any) {
    console.log(
      " ~ file: getCurrentUser.ts:13 ~ getCurrentUser ~ error:",
      error
    );
    return null;
  }
});

export default getCurrentUser;

import prisma from "@/lib/prismadb";

export interface IListingsParams {
  userId?: string;
  guestCount?: number;
  roomCount?: number;
  bathroomCount?: number;
  startDate?: string;
  endDate?: string;
  locationValue?: string;
  category?: string;
}

export default async function getListings(params: IListingsParams) {
  try {
    const {
      userId,
      roomCount,
      guestCount,
      bathroomCount,
      locationValue,
      startDate,
      endDate,
      category,
    } = params;

    let query: any = {};

    if (userId) {
      query.hostId = userId;
    }

    if (category) {
      query.type = category;
    }

    if (roomCount) {
      query.bedrooms = {
        gte: +roomCount,
      };
    }

    if (guestCount) {
      query.maxGuests = {
        gte: +guestCount,
      };
    }

    if (bathroomCount) {
      query.bathrooms = {
        gte: +bathroomCount,
      };
    }

    if (locationValue) {
      query.location = {
        is: {
          country: locationValue,
        },
      };
    }

    if (startDate && endDate) {
      query.NOT = {
        reservations: {
          some: {
            OR: [
              {
                checkOut: { gte: startDate },
                checkIn: { lte: startDate },
              },
              {
                checkIn: { lte: endDate },
                checkOut: { gte: endDate },
              },
            ],
          },
        },
      };
    }

    const listing = await prisma.listing.findMany({
      where: query,
      orderBy: {
        createdAt: "desc",
      },
    });

    const safeListings = listing.map((list) => ({
      ...list,
      createdAt: list.createdAt.toISOString(),
    }));

    return safeListings;
  } catch (error: any) {
    throw new Error(error.message);
  }
}

